    <style>
        @import url('https://fonts.googleapis.com/css2?family=Times+New+Roman:wght@400;700&amp;display=swap');

        body {
            margin: 0;
            padding: 0;
            font-family: 'Times New Roman', serif;
            font-size: 12pt;
            line-height: 1.4;
            max-width: 800px;
            margin: 40px auto;
            padding: 0 20px;
            background: #fff;
            color: #000;
            box-shadow: 0 0 20px rgba(0,0,0,0.1);
        }

        .header {
            text-align: center;
            margin-bottom: 30px;
            border-bottom: 2px solid #000;
            padding-bottom: 15px;
        }

        .title {
            font-size: 18pt;
            font-weight: bold;
            margin: 0;
        }

        .subtitle {
            font-size: 14pt;
            margin: 8px 0 0;
            font-weight: normal;
        }

        .meta {
            font-size: 11pt;
            margin: 20px 0;
            display: flex;
            justify-content: space-between;
            font-style: italic;
        }

        .content {
            text-align: justify;
            margin: 30px 0;
        }

        p {
            margin: 12px 0;
            text-indent: 30px;
