            height: 200px;
            margin: 20px 0;
            background: #f5f5f5;
            border: 2px dashed #999;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 11pt;
            color: #666;
            text-align: center;
            position: relative;
        }

        .placeholder::before {
            content: "Diagram / Chart";
            font-weight: bold;
        }

        table {
            width: 100%;
            border-collapse: collapse;
            margin: 20px 0;
        }

        th, td {
            border: 1px solid #000;
            padding: 8px;
            text-align: left;
        }

        th {
            background: #f0f0f0;
        }

        .footer {
            margin-top: 50px;
