        </div>

        <div class="content">
            <p>[Text block 3 – full verbatim content]</p>
        </div>

        <table>
            <tr>
                <th>Header 1</th>
                <th>Header 2</th>
            </tr>
            <tr>
                <td>[Data cell 1]</td>
                <td>[Data cell 2]</td>
            </tr>
        </table>
    </div>

    <div class="footer">
        [Footer text or page number]
    </div>
